const iconButton=(icon,action,label)=>`<button class='icon-button' data-act='${action}' aria-label='${esc(label)}'>${ic(icon)}</button>`;
function header(label,back=null,right=''){return `<div class='phone-top'>${back?iconButton('back',back,'Back') : ''}<strong>${label}</strong><span class='header-actions'>${right}</span></div>`}
function tabs(which){return `<nav class='bottom-tabs' aria-label='Concept navigation'>${[['library','library','Library'],['sources','radio','Following'],['margins','note','Margins']].map(([id,icon,label])=>`<button data-act='${id}' ${which===id?"aria-current='page' class='selected'":''}>${ic(icon)}${label}</button>`).join('')}</nav>`}
function mini(s){return s.session?`<div class='p-mini-player'><button class='mini-open' data-act='listen'><strong>${esc(title(active(s),s))}</strong><small>${s.playing?'Playing':'Paused'} · ${s.mode==='text'?'Paragraph 12 of 32':time(s.position)}</small></button>${iconButton(s.playing?'pause':'play','toggle-play',s.playing?'Pause':'Play')}</div>`:''}
