function itemRow(i,s){const current=i.id===s.active,hasPosition=i.pos>0||current;return `<div class='v2-item ${current?'current':''}' data-item-row><button class='item-open' data-act='item:${i.id}'><span class='item-type'>${ic(i.type==='Podcast'||i.type==='Audio'?'headphones':'file')}</span><span><strong>${esc(title(i,s))}</strong><small>${esc(i.source)} · ${i.type}</small><span class='row-status'>${current&&s.session?(s.playing?'Playing':'Paused'):hasPosition?'Continue':i.ready?'Ready offline':'Needs connection'}${hasPosition?' · '+time(current?s.position:i.pos)+(i.ready?' · Ready offline':''):i.time?' · '+Math.round(i.time/60)+' min':''}</span></span></button>${iconButton(current&&s.session&&s.playing?'pause':'play','play:'+i.id,(current&&s.playing?'Pause ':'Listen to ')+i.title)}</div>`}
