function marginResults(s){let list=s.notes.filter(n=>s.noteFilter==='Shared'?n.owner:s.noteFilter==='Starred'?n.starred:!n.owner).filter(n=>(n.text+' '+itemFor(s,n.item).title).toLowerCase().includes(s.noteQuery.toLowerCase()));return list.length?list.map(n=>noteRow(n,s)).join(''):`<div class='v2-empty'><h3>${s.noteQuery?'No matching Margins':s.noteFilter==='Starred'?'No starred Margins':'No Margins yet'}</h3><p>${s.noteQuery?'Try another word or an item title.':s.noteFilter==='Starred'?'Star a note from its detail view.':'Add a Margin while listening to keep a thought here.'}</p>${button(s.noteQuery?'Clear search':'Open Library',s.noteQuery?'clear-notes':'library','p-link')}</div>`}
function bottom(content){return `<div class='phone-bottom'>${content}</div>`}
