  dock=`<div class='v2-playback-dock'><div class='v2-position'><label class='sr-only' for='concept-position'>${s.mode==='text'?'Source position':'Audio position'}</label><input type='range' id='concept-position' min='0' max='${a.time||1410}' value='${s.position}' data-input='position'><div class='p-between'><span id='position-label'>${positionLabel(s)}</span><span id='remaining-label'>${s.mode==='text'?Math.round(s.position/14.1)+'%':'−'+time(Math.max(0,(a.time||1410)-s.position))}</span></div></div><div class='transport'>${button(ic('repeat')+'<small>'+(s.mode==='text'?'Previous ¶':'15 sec')+'</small>','backward')}${iconButton(s.playing?'pause':'play','toggle-play',s.playing?'Pause':'Play')}${button(ic('repeat')+'<small>'+(s.mode==='text'?'Next ¶':'15 sec')+'</small>','forward')}</div><div class='v2-play-options'>${button(s.speed+'×','speed','p-link')}${button('Sleep'+(s.sleep==='Off'?'':': '+s.sleep),'sleep','p-link','clock')}</div></div>`;
